"""Generate vendor/espmap_v0_2_1_colormaps.json: espmap v0.2.1's own vik and
lajolla colour tables, frozen for Arrowfield's pair view.

    ESPMAP_PATH=/path/to/espmap-checkout-at-v0.2.1 python vendor/make_espmap_colormaps.py

Run once, by hand, with espmap at exactly v0.2.1 (commit 41a989d); refused
for any other commit. The output is generated data: DO NOT EDIT it. espmap
owns the colour convention (its --selftest asserts warm = negative on vik
and V_min darkest on lajolla); Arrowfield only looks values up in the
frozen tables (palette.py) and never flips or reinterprets them. If espmap
ever changes its maps, palette's parity test reports the drift; following
it is an explicit Arrowfield contract change, never an automatic one.

The lookup rule is the one espmap's colours go through (matplotlib's
Colormap.__call__ on a float t in [0, 1], N = 256): i = min(int(t * N),
N - 1). This script checks that rule against espmap's colormap at 4097
points per map before writing.
"""
import hashlib
import json
import os
import subprocess
import sys
from pathlib import Path

COMMIT = "41a989d6240b56e3c17938dac2084dfc5e1423e4"      # espmap v0.2.1
OUT = Path(__file__).with_name("espmap_v0_2_1_colormaps.json")
MAPS = ("vik", "lajolla")


def table_sha256(rgba):
    return hashlib.sha256(json.dumps(rgba, separators=(",", ":")).encode()).hexdigest()


def main():
    root = Path(os.environ["ESPMAP_PATH"])
    head = subprocess.run(["git", "rev-parse", "HEAD"], cwd=root, capture_output=True, text=True,
                          check=True).stdout.strip()
    if head != COMMIT:
        sys.exit(f"espmap at {head}, not v0.2.1 ({COMMIT}): refusing to vendor tables from another release")
    sys.path.insert(0, str(root))
    import importlib.metadata as md
    import matplotlib
    import esp_map as em
    built = em.build_maps()
    maps = {}
    for name in MAPS:
        cmap = built[name]
        rgba = [[float(v) for v in cmap(i / cmap.N)] for i in range(cmap.N)]
        assert cmap.N == 256 and len(rgba) == 256, name
        for k in range(4097):                     # the lookup rule reproduces espmap's colormap exactly
            t = k / 4096
            i = min(int(t * cmap.N), cmap.N - 1)
            assert [float(v) for v in cmap(t)] == rgba[i], (name, t)
        maps[name] = {"N": cmap.N, "rgba": rgba, "sha256": table_sha256(rgba)}
    doc = {
        "DO_NOT_EDIT": "generated by vendor/make_espmap_colormaps.py from espmap; regenerate, never hand-edit",
        "espmap": {"version": "0.2.1", "commit": COMMIT, "function": "esp_map.build_maps()[name]"},
        "generated_with": {"matplotlib": matplotlib.__version__, "cmcrameri": md.version("cmcrameri")},
        "lookup": "t = clip((V - vmin) / (vmax - vmin), 0, 1); i = min(int(t * N), N - 1); rgba = table[i]",
        "orientation": {"vik": "index 0 (V at vmin, negative) is warm; index N-1 is cool",
                        "lajolla": "index 0 (V_min) is darkest"},
        "attribution": ("Scientific colour maps vik and lajolla, Copyright (c) 2020 Fabio Crameri; "
                        "cmcrameri packaging Copyright (c) 2020 Callum Rollo; MIT License (see "
                        "vendor/LICENSE-cmcrameri). Oriented as espmap v0.2.1 builds them."),
        "maps": maps,
    }
    OUT.write_text(json.dumps(doc, indent=1) + "\n", encoding="utf-8")
    print({k: v["sha256"][:12] for k, v in maps.items()}, "->", OUT)


if __name__ == "__main__":
    main()
